class TokenBucket {
  constructor(cap, ratePerSec) {
    this.cap = cap; this.rate = ratePerSec;
    this.tokens = cap; this.last = 0;
  }
  tryTake(nowMs) {
    const elapsed = (nowMs - this.last) / 1000;
    this.tokens = Math.min(this.cap, this.tokens + elapsed * this.rate);
    this.last = nowMs;
    if (this.tokens >= 1) { this.tokens -= 1; return true; }
    return false;
  }
}
const b = new TokenBucket(3, 1);
const r = [0, 0, 0, 0, 500, 1000, 1000].map((t) => (b.tryTake(t) ? 'Y' : 'N'));
console.log(r.join(''));

function makeLimiter(limit, windowMs) {
  const log = [];
  return (now) => {
    while (log.length && log[0] <= now - windowMs) log.shift();
    if (log.length < limit) { log.push(now); return true; }
    return false;
  };
}
const allow = makeLimiter(2, 1000);
console.log([0, 100, 200, 1000, 1100, 1150].map((t) => (allow(t) ? 1 : 0)).join(''));

