let calls = 0;
const inflight = new Map();
function load(key) {
  if (inflight.has(key)) return inflight.get(key);
  const p = new Promise((r) => setTimeout(() => { calls++; r(key.toUpperCase()); }, 10))
    .finally(() => inflight.delete(key));
  inflight.set(key, p);
  return p;
}
Promise.all([load('a'), load('a'), load('b')]).then((v) => {
  console.log(v.join(','), calls, inflight.size);
});

let tokens = 1;
const tick = () => new Promise((r) => setTimeout(r, 0));
async function take(name) {
  const t = tokens;
  await tick();
  if (t > 0) { tokens = t - 1; return name + ':ok'; }
  return name + ':no';
}
Promise.all([take('a'), take('b')]).then((r) => console.log(r.join(' '), tokens));
